<template>
    <CustomerLayout>
        <div class="mx-auto max-w-6xl px-4 py-8 sm:px-6 sm:py-12 lg:px-8">
            <div class="mb-8 grid gap-6 lg:grid-cols-[1.25fr_.75fr] lg:items-end"><div><p class="eyebrow">Made just for you</p><h1 class="mt-3 font-serif text-3xl font-bold tracking-tight text-brand-900 sm:text-5xl">Your idea, our oven.</h1><p class="mt-4 max-w-2xl text-sm leading-7 text-brand-500">Choose a cake base, size and flavour, then share the design you have in mind. Our cake team will review it and call you to confirm the final details.</p></div><div class="rounded-[1.5rem] border border-gold-200 bg-gold-50 p-4 text-sm text-brand-700"><div class="flex items-center gap-3"><span class="flex h-10 w-10 items-center justify-center rounded-xl bg-white text-gold-600">✦</span><div><p class="font-bold text-brand-900">A personal cake consultation</p><p class="mt-1 text-xs leading-5 text-brand-600">{{ settings.custom_cake_info || 'We will confirm decoration, availability and final price with you.' }}</p></div></div></div></div>

            <form id="custom-cake-form" @submit.prevent="submitOrder" class="grid gap-6 lg:grid-cols-[minmax(0,1.35fr)_minmax(300px,.65fr)]">
                <div class="space-y-5">
                    <section v-if="availableCustomizableProducts.length" class="rounded-[1.6rem] border border-gold-200 bg-gradient-to-br from-gold-50 to-white p-5 shadow-soft sm:p-7"><div class="mb-5 flex items-start gap-3"><span class="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-gold-100 text-sm font-bold text-gold-700">1</span><div><h2 class="font-serif text-2xl font-bold text-brand-900">Choose a cake base</h2><p class="mt-1 text-sm text-brand-500">Select the product you want our cake team to customize.</p></div></div><div class="grid gap-3 sm:grid-cols-2"><button v-for="product in availableCustomizableProducts" :key="product.id" type="button" @click="selectProduct(product)" :class="form.product_id == product.id ? 'border-brand-600 bg-brand-50 ring-2 ring-brand-100' : 'border-brand-200 bg-white hover:border-gold-400'" class="group flex items-center gap-3 rounded-2xl border-2 p-3 text-left transition"><div class="h-16 w-16 shrink-0 overflow-hidden rounded-xl bg-cream-100"><img v-if="product.image" :src="assetUrl(product.image)" :alt="product.name" class="h-full w-full object-cover"/><span v-else class="flex h-full items-center justify-center text-2xl">🍰</span></div><span class="min-w-0 flex-1"><strong class="block truncate text-sm text-brand-900">{{ product.name }}</strong><span class="mt-1 block text-xs font-semibold text-gold-700">From {{ money(product.effective_price) }}</span><span class="mt-1 block text-[11px] text-brand-400">{{ customizationLabel(product.customization_mode) }}</span></span><span v-if="form.product_id == product.id" class="text-brand-600">✓</span></button></div></section>

                    <section class="rounded-[1.6rem] border border-brand-100 bg-white p-5 shadow-soft sm:p-7"><div class="mb-6 flex items-start gap-3"><span class="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-brand-100 text-sm font-bold text-brand-700">2</span><div><h2 class="font-serif text-2xl font-bold text-brand-900">How should we prepare it?</h2><p class="mt-1 text-sm text-brand-500">Choose an outlet and the handover method allowed for this cake.</p></div></div><div v-if="pickupAllowed || homeDeliveryAllowed" class="mb-5 grid gap-3 sm:grid-cols-2"><label v-if="pickupAllowed" :class="form.delivery_type === 'pickup' ? 'border-brand-600 bg-brand-50 ring-2 ring-brand-100' : 'border-brand-200 bg-white hover:border-brand-400'" class="cursor-pointer rounded-2xl border-2 p-4 transition"><input v-model="form.delivery_type" type="radio" value="pickup" class="sr-only"/><p class="text-sm font-bold text-brand-900">Branch pickup</p><p class="mt-1 text-xs leading-5 text-brand-500">Collect it fresh from your selected outlet.</p></label><label v-if="homeDeliveryAllowed" :class="form.delivery_type === 'home_delivery' ? 'border-brand-600 bg-brand-50 ring-2 ring-brand-100' : 'border-brand-200 bg-white hover:border-brand-400'" class="cursor-pointer rounded-2xl border-2 p-4 transition"><input v-model="form.delivery_type" type="radio" value="home_delivery" class="sr-only"/><p class="text-sm font-bold text-brand-900">Home delivery</p><p class="mt-1 text-xs leading-5 text-brand-500">We will bring it to your selected area.</p></label></div><div class="mb-5 rounded-2xl bg-brand-50 px-4 py-3 text-xs leading-5 text-brand-600"><strong class="text-brand-800">{{ form.delivery_type === 'pickup' ? 'Pickup from our outlet' : 'Home delivery available' }}</strong><br>{{ pickupAllowed && homeDeliveryAllowed ? 'You can change this choice before submitting.' : pickupAllowed ? 'This cake is currently available for branch pickup.' : 'This cake is currently available for home delivery.' }}</div><label class="field-label">{{ form.delivery_type === 'pickup' ? 'Pickup branch' : 'Serving outlet' }}<select v-model="form.branch_id" required class="field-input"><option value="">Choose an outlet</option><option v-for="branch in branches" :key="branch.id" :value="branch.id">{{ branch.name }}{{ branch.name_bn ? ` · ${branch.name_bn}` : '' }}</option></select></label><div v-if="selectedBranch" class="mt-3 rounded-2xl border border-brand-100 bg-cream-50 px-4 py-3 text-xs leading-5 text-brand-600"><strong class="text-brand-800">{{ selectedBranch.name }}</strong><br>{{ selectedBranch.address || 'Lake View outlet' }}<span v-if="selectedBranch.phones?.[0]"> · {{ selectedBranch.phones[0] }}</span></div><div v-if="form.delivery_type === 'home_delivery'" class="mt-4"><label class="field-label">Delivery area<select v-model="form.delivery_area_id" required class="field-input"><option value="">Choose your area</option><optgroup v-if="sadarAreas.length" label="Satkhira Sadar"><option v-for="area in sadarAreas" :key="area.id" :value="area.id">{{ area.name }} · {{ money(area.delivery_charge) }}</option></optgroup><optgroup v-if="ruralAreas.length" label="Satkhira Sadar Rural"><option v-for="area in ruralAreas" :key="area.id" :value="area.id">{{ area.name }} · {{ money(area.delivery_charge) }}</option></optgroup><optgroup v-if="outsideAreas.length" label="Outside Sadar / Upazila"><option v-for="area in outsideAreas" :key="area.id" :value="area.id">{{ area.name }} · {{ money(area.delivery_charge) }}</option></optgroup><optgroup v-if="nationalAreas.length" label="All Bangladesh · Courier"><option v-for="area in nationalAreas" :key="area.id" :value="area.id">{{ area.name }} · {{ money(area.delivery_charge) }}</option></optgroup></select></label><div v-if="selectedArea" class="mt-3 rounded-2xl bg-sage-50 p-4 text-xs leading-5 text-sage-700"><p class="font-bold">Delivery to {{ selectedArea.name }}</p><p class="mt-1">Charge: {{ money(selectedArea.delivery_charge) }}</p></div><label class="field-label mt-4">Full delivery address<textarea v-model="form.customer_address" required rows="3" placeholder="House, road, area and a nearby landmark" class="field-input"></textarea></label></div></section>

                    <section class="rounded-[1.6rem] border border-brand-100 bg-white p-5 shadow-soft sm:p-7"><div class="mb-6 flex items-start gap-3"><span class="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-brand-100 text-sm font-bold text-brand-700">3</span><div><h2 class="font-serif text-2xl font-bold text-brand-900">Tell us about the cake</h2><p class="mt-1 text-sm text-brand-500">The available sizes and prices come from the selected cake product.</p></div></div><div class="grid gap-4 sm:grid-cols-3"><label class="field-label">Occasion<input v-model="form.cake_type" type="text" placeholder="Birthday, wedding..." class="field-input"/></label><label class="field-label">Cake size<select v-model="form.cake_size" :required="!!selectedProduct" class="field-input"><option value="">Choose size</option><option v-for="size in sizeOptions" :key="size.label" :value="size.label">{{ size.label }} · {{ money(size.discount_price > 0 ? size.discount_price : size.price) }}</option></select></label><label class="field-label">Flavour<select v-model="form.cake_flavor" class="field-input"><option value="">Choose flavour</option><option>Vanilla</option><option>Chocolate</option><option>Strawberry</option><option>Black Forest</option><option>White Forest</option><option>Red Velvet</option><option>Blueberry</option><option>Lemon</option><option>Orange</option></select></label></div><div v-if="selectedSize" class="mt-4 rounded-2xl border border-gold-200 bg-gold-50 px-4 py-3 text-sm text-brand-700"><span class="font-bold">Estimated cake price: {{ money(selectedSize.discount_price > 0 ? selectedSize.discount_price : selectedSize.price) }}</span><span class="ml-2 text-xs text-brand-500">Final decoration price will be confirmed by our team.</span></div><label class="field-label mt-4">Message on cake <span class="font-normal text-brand-400">(optional)</span><input v-model="form.message_on_cake" type="text" placeholder="e.g. Happy Birthday John!" class="field-input"/></label><div class="mt-4 grid gap-4 sm:grid-cols-2"><label class="field-label">Preferred date<input v-model="form.delivery_date" type="date" required :min="minDate" class="field-input"/></label><label class="field-label">Preferred time <span class="font-normal text-brand-400">(optional)</span><input v-model="form.delivery_time" type="time" class="field-input"/></label></div><div class="mt-5"><div class="mb-2 flex items-end justify-between gap-3"><label class="field-label">Design reference <span class="font-normal text-brand-400">(optional)</span></label><span class="text-[11px] text-brand-400">JPG, PNG · max 2MB</span></div><input ref="fileInput" @change="handleFile" type="file" accept="image/*" class="sr-only"/><button type="button" @click="$refs.fileInput.click()" class="group w-full rounded-2xl border-2 border-dashed border-brand-200 bg-cream-50 p-5 text-left transition hover:border-gold-400"><div v-if="designPreview" class="flex items-center gap-4"><img :src="designPreview" alt="Cake design preview" class="h-20 w-20 rounded-xl object-cover"/><span class="min-w-0 flex-1"><strong class="block truncate text-sm text-brand-800">{{ designImage.name }}</strong><small class="mt-1 block text-xs text-brand-400">Click to replace this image</small></span><span class="text-xs font-bold text-brand-600">Change</span></div><div v-else class="flex items-center gap-4"><span class="flex h-12 w-12 shrink-0 items-center justify-center rounded-xl bg-white text-2xl">🖼️</span><span><strong class="block text-sm text-brand-800">Upload an inspiration image</strong><small class="mt-1 block text-xs text-brand-400">A clear reference helps us match your expectations.</small></span></div></button><div v-if="fileError" class="mt-2 rounded-xl bg-red-50 px-3 py-2 text-xs font-semibold text-red-600">{{ fileError }}</div></div><label class="field-label mt-5">Additional notes <span class="font-normal text-brand-400">(optional)</span><textarea v-model="form.notes" rows="3" placeholder="Colour theme, decoration, allergies or anything else..." class="field-input"></textarea></label></section>
                    <div class="grid gap-2" v-if="Object.keys(errors).length"><p v-for="(error, key) in errors" :key="key" class="rounded-xl border border-red-200 bg-red-50 px-4 py-2 text-sm text-red-600">{{ error }}</p></div>
                </div>

                <aside class="lg:sticky lg:top-24 lg:self-start"><div class="rounded-[1.6rem] border border-brand-100 bg-brand-950 p-5 text-cream-50 shadow-card sm:p-6"><p class="text-xs font-bold uppercase tracking-[.18em] text-brand-300">Step 4 · Review</p><h2 class="mt-2 font-serif text-2xl font-bold">Your cake request</h2><div class="mt-6 space-y-4 border-b border-white/10 pb-5 text-sm"><div class="flex items-start justify-between gap-4"><span class="text-brand-300">Cake</span><span class="max-w-[180px] text-right font-semibold text-cream-50">{{ selectedProduct?.name || 'Custom cake' }}</span></div><div class="flex items-start justify-between gap-4"><span class="text-brand-300">Size</span><span class="text-right font-semibold text-cream-50">{{ form.cake_size || 'Choose a size' }}</span></div><div class="flex items-start justify-between gap-4"><span class="text-brand-300">Delivery</span><span class="text-right font-semibold text-cream-50">{{ form.delivery_type === 'pickup' ? 'Branch pickup' : 'Home delivery' }}</span></div><div class="flex items-start justify-between gap-4"><span class="text-brand-300">Branch</span><span class="max-w-[180px] text-right font-semibold text-cream-50">{{ selectedBranch?.name || 'Choose an outlet' }}</span></div></div><div class="flex items-center justify-between py-5"><span class="text-sm text-brand-300">Estimated total</span><span class="font-serif text-2xl font-bold text-gold-300">{{ selectedSize ? money(Number(selectedSize.discount_price > 0 ? selectedSize.discount_price : selectedSize.price) + (form.delivery_type === 'home_delivery' ? Number(selectedArea?.delivery_charge || 0) : 0)) : 'To confirm' }}</span></div><div class="rounded-2xl bg-white/10 p-4 text-xs leading-5 text-brand-200">We will review the design, confirm availability and call you before preparation.</div><button type="submit" form="custom-cake-form" :disabled="processing" class="mt-5 flex w-full items-center justify-center gap-2 rounded-2xl bg-gold-500 px-5 py-4 text-sm font-bold text-brand-950 transition hover:bg-gold-400 disabled:cursor-not-allowed disabled:opacity-50">{{ processing ? 'Sending request...' : 'Submit cake request →' }}</button></div><div class="mt-3 rounded-2xl border border-brand-100 bg-white p-4 text-xs leading-5 text-brand-500 shadow-soft"><p class="font-bold text-brand-800">Need a quick answer?</p><p class="mt-1">Send the request and our cake team will call to confirm the details.</p></div></aside>
            </form>
        </div>
    </CustomerLayout>
</template>

<script setup>
import CustomerLayout from '@/Layouts/CustomerLayout.vue';
import { router, usePage } from '@inertiajs/vue3';
import { ref, computed, watch } from 'vue';

const props = defineProps({ branches: Array, deliveryAreas: Array, customizableProducts: Array, auth: Object, selectedBranchId: [Number, String], deliveryMode: String });
const page = usePage();
const settings = computed(() => page.props.settings || {});
const errors = computed(() => page.props.errors || {});
const processing = ref(false); const designImage = ref(null); const designPreview = ref(''); const fileError = ref('');
const form = ref({ branch_id: props.selectedBranchId || '', product_id: '', delivery_type: 'pickup', delivery_area_id: '', customer_name: '', customer_phone: '', customer_email: '', customer_address: '', cake_type: '', cake_size: '', cake_flavor: '', message_on_cake: '', delivery_date: '', delivery_time: '', notes: '' });
if (props.auth?.user) { form.value.customer_name = props.auth.user.name || ''; form.value.customer_phone = props.auth.user.phone || ''; form.value.customer_email = props.auth.user.email || ''; }
const selectedBranch = computed(() => props.branches?.find(branch => branch.id == form.value.branch_id));
const availableCustomizableProducts = computed(() => (props.customizableProducts || []).filter(product => !product.branches?.length || product.branches.some(branch => Number(branch.id) === Number(form.value.branch_id))));
const selectedProduct = computed(() => availableCustomizableProducts.value.find(product => product.id == form.value.product_id));
const defaultSizes = [{ label: '500 gm', price: 0, discount_price: 0 }, { label: '1 kg', price: 0, discount_price: 0 }, { label: '1.5 kg', price: 0, discount_price: 0 }, { label: '2 kg', price: 0, discount_price: 0 }];
const sizeOptions = computed(() => selectedProduct.value?.cake_sizes?.length ? selectedProduct.value.cake_sizes : defaultSizes);
const selectedSize = computed(() => sizeOptions.value.find(size => size.label === form.value.cake_size));
const customizationLabel = mode => ({ ready_and_customization: 'Ready + customization', customization_only: 'Customization only' }[mode] || 'Customization');
const assetUrl = path => path?.startsWith('http') ? path : '/storage/' + path;
const selectProduct = product => { form.value.product_id = product.id; form.value.cake_type = form.value.cake_type || product.name; form.value.cake_size = product.cake_sizes?.[0]?.label || ''; form.value.delivery_type = product.allow_pickup === false ? 'home_delivery' : 'pickup'; };
const allDeliveryAreas = computed(() => props.deliveryAreas || []);
const normalizedAreaName = name => String(name || '').toLowerCase().replace(/[()\s_-]+/g, ' ').trim();
const branchDeliveryAreas = computed(() => { if (!form.value.branch_id) return []; const branchId = Number(form.value.branch_id); const scoped = allDeliveryAreas.value.filter(area => area.branch_id == null || Number(area.branch_id) === branchId); const branchSpecific = scoped.filter(area => Number(area.branch_id) === branchId); const global = scoped.filter(area => area.branch_id == null); const seen = new Set(); return [...branchSpecific, ...global].filter(area => { const key = normalizedAreaName(area.name); if (seen.has(key)) return false; seen.add(key); return true; }); });
const serviceScope = area => area?.service_scope || (area?.zone_type === 'outside_sadar' ? 'outside_sadar' : 'sadar');
const sadarAreas = computed(() => branchDeliveryAreas.value.filter(area => serviceScope(area) === 'sadar'));
const ruralAreas = computed(() => branchDeliveryAreas.value.filter(area => serviceScope(area) === 'sadar_rural'));
const outsideAreas = computed(() => branchDeliveryAreas.value.filter(area => serviceScope(area) === 'outside_sadar'));
const nationalAreas = computed(() => branchDeliveryAreas.value.filter(area => serviceScope(area) === 'national'));
const selectedArea = computed(() => branchDeliveryAreas.value.find(area => area.id == form.value.delivery_area_id));
const pickupAllowed = computed(() => selectedProduct.value ? selectedProduct.value.allow_pickup !== false : ['pickup', 'both'].includes(props.deliveryMode || 'both'));
const homeDeliveryAllowed = computed(() => selectedProduct.value ? selectedProduct.value.allow_home_delivery !== false : ['home_delivery', 'both'].includes(props.deliveryMode || 'both'));
const minDate = computed(() => { const date = new Date(); date.setDate(date.getDate() + 1); return date.toISOString().split('T')[0]; });
const money = value => '৳' + Number(value || 0).toLocaleString('en-BD', { maximumFractionDigits: 0 });
watch([pickupAllowed, homeDeliveryAllowed], ([pickup, home]) => { if (!pickup && home) form.value.delivery_type = 'home_delivery'; if (pickup && !home) form.value.delivery_type = 'pickup'; });
watch(() => form.value.delivery_type, type => { if (type === 'pickup') { form.value.delivery_area_id = ''; form.value.customer_address = ''; } });
watch(() => form.value.branch_id, () => { if (form.value.delivery_area_id && !selectedArea.value) form.value.delivery_area_id = ''; if (form.value.product_id && !availableCustomizableProducts.value.some(product => product.id == form.value.product_id)) form.value.product_id = ''; });
const handleFile = event => { const file = event.target.files?.[0] || null; fileError.value = ''; if (file && file.size > 2 * 1024 * 1024) { designImage.value = null; designPreview.value = ''; fileError.value = 'Please choose an image smaller than 2MB.'; event.target.value = ''; return; } designImage.value = file; designPreview.value = file ? URL.createObjectURL(file) : ''; };
const submitOrder = () => { if (processing.value) return; if (form.value.delivery_type === 'home_delivery') { const address = String(form.value.customer_address || '').trim(); if (!address) { document.querySelector('#custom-cake-form textarea')?.focus(); return; } form.value.customer_address = address; } processing.value = true; const formData = new FormData(); Object.entries(form.value).forEach(([key, value]) => { if (value !== null && value !== undefined) formData.append(key, value); }); if (designImage.value) formData.append('design_image', designImage.value); router.post(route('custom-cake.store'), formData, { forceFormData: true, onFinish: () => { processing.value = false; } }); };
</script>
